import { Component } from '@angular/core';
import { SubHeroLogoComponent } from 'src/app/shared-ui/sub-hero-logo/sub-hero-logo.component';

@Component({
  standalone: true,
  imports: [
    SubHeroLogoComponent,
  ],
  selector: 'app-hero-section',
  templateUrl: './hero-section.component.html',
})
export class HeroSectionComponent {
  image = '../../assets/images/hero-1.png';
}
<section class="main-content">
  <div class="carousel">
    <div class="carousel-image"><img [src]="image" alt="delicious pie" /></div>
  </div>
  <app-sub-hero-logo>
    <ng-container title>Pies of the Week</ng-container>
    <ng-container sub-title>Enjoy a weekly selection of our favorite pies</ng-container>
  </app-sub-hero-logo>
</section>
